// Traduce el payload del proveedor de inbound email contratado a la forma
// neutra que espera POST /api/integraciones/correo (src/ingest/correo/tipos.ts).
// Puro reordenamiento de campos: NINGUN calculo tributario ni contable.
const p = $input.first().json;
return [{
  json: {
    messageId: p.messageId ?? null,
    remitenteEmail: p.from ?? p.envelope?.from ?? '',
    remitenteNombre: p.fromName ?? null,
    destinatarios: p.to ? [].concat(p.to) : [],
    asunto: p.subject ?? null,
    headers: p.headers ?? {},
    adjuntos: (p.attachments ?? []).map((a) => ({
      nombreArchivo: a.filename ?? null,
      contentType: a.contentType ?? null,
      contenidoBase64: a.content,
    })),
    tamanoBytes: p.tamanoBytes ?? null,
  },
}];
